/**
 * The states fixture in element form: a member's `*.states.ts` in
 * `@polymorph/elements-ui`, generated by `pnpm shells` from the member's
 * description, with the entry names the React fixture gives them.
 *
 * An entry is markup a page writes, and what a page sets from script once the
 * elements are defined: properties no attribute can hold (a function, a value
 * an expression makes) and listeners. The conformance runner's overrides reach
 * the first element of the entry's `subject` tag: a probe value as a property,
 * and a spy as a listener for the event of its handler's name.
 */

import { encode } from './attributes'
import { attributeOf, eventOf, propertyOf, type Codec } from './definition'
import { inheritedMethod, PolyElement } from './element'

/**
 * An element of an entry's markup, as its script reads it: its properties by
 * name, each of any type, because a member's prop takes the place of the
 * element's own property of that name (a Dialog's `title`).
 */
export type FixtureElement = EventTarget & Record<string, unknown>

/** The entry's elements by tag and their index among that tag's, in document order. */
export type FindElement = (tag: string, index: number) => FixtureElement

export interface StateEntry {
  name: string
  /** The entry as a page writes it. */
  html: string
  /** The tag of the element the runner's overrides reach: the first one in the markup. */
  subject?: string
  /** What the page sets from script once the elements are defined, before they render. */
  setup?: (find: FindElement) => void
  /**
   * Text typed into a field once the field is in the document, as a reader
   * types it, for a state no attribute sets (Command's query): the field's
   * selector, searched in the document because an overlay portals, and the text.
   */
  types?: { into: string; text: string }
  /** A control pressed once it is in the document, for a state only a press reaches: its selector. */
  presses?: string
  /**
   * Words selected once their element is in the document and holds them, as a
   * reader selects them, for a state only a selection reaches (the words
   * RichTextInput draws its selection bar at): the element's selector and the
   * words.
   */
  selects?: { in: string; text: string }
  /** Attributes the rendered root must carry. `null` asserts absence. */
  expect?: Record<string, string | null>
  /** The entry renders nothing at all, by design. */
  rendersNothing?: true
}

export interface ComponentStates {
  component: string
  entries: StateEntry[]
}

/**
 * Calls `handler` with each `type` event's `detail`, as the callback of a
 * React fixture is called with its first argument.
 */
export function listen(
  element: FixtureElement,
  type: string,
  handler: (detail: never) => unknown,
): void {
  element.addEventListener(type, (event) => {
    handler((event as CustomEvent<unknown>).detail as never)
  })
}

/**
 * Values an entry holds, as the page around a controlled member holds them:
 * each element property bound to a value is set to it now and each time the
 * value is set (a row's `selected`, set by the row's own click).
 */
export interface Holding<Values extends Record<string, unknown>> {
  bind<Name extends keyof Values>(name: Name, element: FixtureElement, property: string): void
  set<Name extends keyof Values>(name: Name, value: Values[Name]): void
}

export function holding<Values extends Record<string, unknown>>(initial: Values): Holding<Values> {
  const values = { ...initial }
  const bound = new Map<keyof Values, [FixtureElement, string][]>()
  return {
    bind(name, element, property) {
      bound.set(name, [...(bound.get(name) ?? []), [element, property]])
      element[property] = values[name]
    },
    set(name, value) {
      values[name] = value
      for (const [element, property] of bound.get(name) ?? []) element[property] = value
    },
  }
}

/**
 * An element a fixture passes inside a value, where a node is data (a
 * DescriptionList detail, a DataTable cell): a member's element with each prop
 * set through its property and each `on*` handler a listener for its event, or
 * a plain element with each prop an attribute; then its children, text as
 * text and a node as it is. A `<template>` takes its children as its content.
 */
/**
 * Sets a member's prop on its element as a page's script does: through its
 * property, or, for a prop named as a method the element inherits, which has
 * no property, through its attribute (`undefined` and `null` remove it).
 */
export function assign(element: FixtureElement, name: string, value: unknown): void {
  const property = propertyOf(name)
  const definition =
    element instanceof PolyElement
      ? (element.constructor as typeof PolyElement).definition
      : undefined
  const codec = definition?.props[name]
  if (codec === undefined || !inheritedMethod(property)) {
    element[property] = value
    return
  }
  const text = encode(codec as Codec, value)
  const host = element as unknown as Element
  if (text === null) host.removeAttribute(attributeOf(name))
  else host.setAttribute(attributeOf(name), text)
}

export function create(
  tag: string,
  props: object = {},
  children: readonly unknown[] = [],
): FixtureElement {
  const element = document.createElement(tag)
  const properties = element as unknown as FixtureElement
  const member = element instanceof PolyElement
  for (const [name, value] of Object.entries(props) as [string, unknown][]) {
    if (value === undefined) continue
    if (member && /^on[A-Z]/.test(name) && typeof value === 'function') {
      listen(properties, eventOf(name), value as (detail: never) => unknown)
    } else if (member) assign(properties, name, value)
    else element.setAttribute(name, String(value))
  }
  const target = element instanceof HTMLTemplateElement ? element.content : element
  for (const child of children) target.append(child instanceof Node ? child : String(child))
  return properties
}
